package com.starafktimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Area;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

public class StarAfkTimerOverlay extends Overlay
{
    private static final double SECONDS_PER_GAME_TICK = 0.6;

    private static final double SPEC_ORB_DIAMETER = 26.0;
    private static final int SPEC_ORB_X_OFFSET = 27;
    private static final int SPEC_ORB_PADDING = 2;

    private static final int SPEC_TEXT_WIDTH = 33;
    private static final int SPEC_TEXT_HEIGHT = 22;
    private static final int SPEC_TEXT_PADDING = 2;
    private static final int SPEC_TEXT_ARC = 8;

    private final Client client;
    private final StarAfkTimerPlugin plugin;
    private final StarAfkTimerConfig config;

    @Inject
    StarAfkTimerOverlay(Client client, StarAfkTimerPlugin plugin, StarAfkTimerConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(OverlayPriority.HIGHEST);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.shouldRenderOverlay())
        {
            return null;
        }

        Dimension canvasSize = graphics.getClipBounds().getSize();

        Color overlayColor = getOverlayColor();

        if (overlayColor.getAlpha() > 0)
        {
            drawDimOverlay(graphics, canvasSize, overlayColor);
        }

        String mainText = getMainText();
        String tierText = getTierText();

        Font originalFont = graphics.getFont();

        graphics.setFont(new Font("SansSerif", Font.BOLD, 34));
        drawCenteredText(graphics, mainText, canvasSize.width, canvasSize.height / 2 - 6);

        graphics.setFont(new Font("SansSerif", Font.BOLD, 22));
        drawCenteredText(graphics, tierText, canvasSize.width, canvasSize.height / 2 + 28);

        graphics.setFont(originalFont);
        return null;
    }

    private Color getOverlayColor()
    {
        Color baseColor = config.overlayColor();
        int alpha = Math.max(0, Math.min(255, config.overlayOpacity()));

        return new Color(
                baseColor.getRed(),
                baseColor.getGreen(),
                baseColor.getBlue(),
                alpha
        );
    }

    private void drawDimOverlay(Graphics2D graphics, Dimension canvasSize, Color overlayColor)
    {
        Area overlayArea = new Area(new Rectangle(0, 0, canvasSize.width, canvasSize.height));

        if (config.showChatbox())
        {
            subtractWidgetBounds(overlayArea, InterfaceID.Chatbox.UNIVERSE, 0);
            subtractWidgetBounds(overlayArea, InterfaceID.Chatbox.CHATAREA, 0);
            subtractWidgetBounds(overlayArea, InterfaceID.ToplevelOsrsStretch.CHAT_CONTAINER, 0);
            subtractWidgetBounds(overlayArea, InterfaceID.ToplevelPreEoc.CHAT_CONTAINER, 0);
        }

        if (config.showSpecialAttackOrb())
        {
            subtractSpecialAttackOrbAndText(overlayArea);
        }

        graphics.setColor(overlayColor);
        graphics.fill(overlayArea);
    }

    private void subtractWidgetBounds(Area overlayArea, int componentId, int padding)
    {
        Widget widget = client.getWidget(componentId);

        if (widget == null || widget.isHidden())
        {
            return;
        }

        Rectangle bounds = widget.getBounds();

        if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
        {
            return;
        }

        Rectangle paddedBounds = new Rectangle(
                bounds.x - padding,
                bounds.y - padding,
                bounds.width + padding * 2,
                bounds.height + padding * 2
        );

        overlayArea.subtract(new Area(paddedBounds));
    }

    private void subtractSpecialAttackOrbAndText(Area overlayArea)
    {
        Widget widget = client.getWidget(InterfaceID.Orbs.ORB_SPECENERGY);

        if (widget == null || widget.isHidden())
        {
            return;
        }

        Rectangle bounds = widget.getBounds();

        if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
        {
            return;
        }

        subtractSpecialAttackOrbCircle(overlayArea, bounds);
        subtractSpecialAttackTextArea(overlayArea, bounds);
    }

    private void subtractSpecialAttackOrbCircle(Area overlayArea, Rectangle bounds)
    {
        double diameter = SPEC_ORB_DIAMETER + SPEC_ORB_PADDING * 2.0;
        double x = bounds.x + SPEC_ORB_X_OFFSET - SPEC_ORB_PADDING;
        double y = bounds.y + (bounds.height / 2.0 - SPEC_ORB_DIAMETER / 2.0) - SPEC_ORB_PADDING;

        overlayArea.subtract(new Area(new Ellipse2D.Double(x, y, diameter, diameter)));
    }

    private void subtractSpecialAttackTextArea(Area overlayArea, Rectangle bounds)
    {
        double x = bounds.x - SPEC_TEXT_PADDING;
        double y = bounds.y + (bounds.height / 2.0 - SPEC_TEXT_HEIGHT / 2.0) - SPEC_TEXT_PADDING;
        double width = SPEC_TEXT_WIDTH + SPEC_TEXT_PADDING * 2.0;
        double height = SPEC_TEXT_HEIGHT + SPEC_TEXT_PADDING * 2.0;

        overlayArea.subtract(new Area(new RoundRectangle2D.Double(
                x,
                y,
                width,
                height,
                SPEC_TEXT_ARC,
                SPEC_TEXT_ARC
        )));
    }

    private String getMainText()
    {
        if (plugin.getEstimatedLayerTicks() >= 0)
        {
            return formatTicks(plugin.getEstimatedLayerTicks()) + " Remaining";
        }

        return "Estimating...";
    }

    private String getTierText()
    {
        if (plugin.getStarTier() > 0)
        {
            return "T" + plugin.getStarTier();
        }

        return "";
    }

    private void drawCenteredText(Graphics2D graphics, String text, int canvasWidth, int y)
    {
        if (text == null || text.isEmpty())
        {
            return;
        }

        FontMetrics metrics = graphics.getFontMetrics();
        int x = (canvasWidth - metrics.stringWidth(text)) / 2;

        graphics.setColor(Color.BLACK);
        graphics.drawString(text, x + 2, y + 2);

        graphics.setColor(Color.WHITE);
        graphics.drawString(text, x, y);
    }

    private String formatTicks(int ticks)
    {
        int totalSeconds = (int) Math.round(ticks * SECONDS_PER_GAME_TICK);
        int minutes = totalSeconds / 60;
        int seconds = totalSeconds % 60;
        return String.format("%d:%02d", minutes, seconds);
    }
}

package com.starafktimer;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup("starafktimer")
public interface StarAfkTimerConfig extends Config
{
	@ConfigItem(
			position = 0,
			keyName = "enabled",
			name = "Enabled",
			description = "Enable the Shooting Star AFK timer overlay"
	)
	default boolean enabled()
	{
		return true;
	}

	@ConfigItem(
			position = 1,
			keyName = "toggleHotkey",
			name = "Toggle hotkey",
			description = "Hotkey to toggle the overlay on or off until pressed again"
	)
	default Keybind toggleHotkey()
	{
		return Keybind.NOT_SET;
	}

	@Alpha
	@ConfigItem(
			position = 2,
			keyName = "overlayColor",
			name = "Overlay color",
			description = "Color of the screen overlay"
	)
	default Color overlayColor()
	{
		return new Color(0, 0, 0, 210);
	}

	@Range(
			min = 0,
			max = 255
	)
	@ConfigItem(
			position = 3,
			keyName = "overlayOpacity",
			name = "Overlay opacity",
			description = "How strong the overlay appears"
	)
	default int overlayOpacity()
	{
		return 210;
	}

	@ConfigItem(
			position = 4,
			keyName = "showChatbox",
			name = "Show chatbox",
			description = "Leave the chatbox visible through the dim overlay"
	)
	default boolean showChatbox()
	{
		return false;
	}

	@ConfigItem(
			position = 5,
			keyName = "showSpecialAttackOrb",
			name = "Show special attack orb",
			description = "Leave the special attack orb and percentage visible through the dim overlay"
	)
	default boolean showSpecialAttackOrb()
	{
		return false;
	}

	@ConfigItem(
			position = 6,
			keyName = "disableOnHover",
			name = "Disable on hover",
			description = "Hide the overlay while your mouse is over the game canvas"
	)
	default boolean disableOnHover()
	{
		return false;
	}

	@ConfigItem(
			position = 7,
			keyName = "hideOnMouseMovement",
			name = "Hide on mouse movement",
			description = "Hide the overlay after moving your mouse"
	)
	default boolean hideOnMouseMovement()
	{
		return false;
	}

	@Range(
			min = 1,
			max = 100
	)
	@ConfigItem(
			position = 8,
			keyName = "mouseIdleGameTicks",
			name = "Reappear after idle (ticks)",
			description = "How many game ticks your mouse must be idle before the overlay appears again. 1 game tick = 0.6 seconds"
	)
	default int mouseIdleGameTicks()
	{
		return 5;
	}

	@ConfigItem(
			position = 9,
			keyName = "hideOnNonStarClick",
			name = "Hide on non-star click",
			description = "Hide the overlay when left-clicking anything other than the current Shooting Star. Click the star again to show it"
	)
	default boolean hideOnNonStarClick()
	{
		return false;
	}
}

package com.starafktimer;

import com.google.inject.Provides;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

@PluginDescriptor(
        name = "Star AFK Timer",
        description = "Dims the screen while mining Shooting Stars and shows a simple current-layer timer",
        tags = {"shooting", "stars", "mining", "afk", "overlay", "timer"}
)
public class StarAfkTimerPlugin extends Plugin
{
    private static final int STAR_HEALTH_NPC = 10629;

    private static final int STAR_T1_OBJECT = 41229;
    private static final int STAR_T2_OBJECT = 41228;
    private static final int STAR_T3_OBJECT = 41227;
    private static final int STAR_T4_OBJECT = 41226;
    private static final int STAR_T5_OBJECT = 41225;
    private static final int STAR_T6_OBJECT = 41224;
    private static final int STAR_T7_OBJECT = 41223;
    private static final int STAR_T8_OBJECT = 41021;
    private static final int STAR_T9_OBJECT = 41020;

    private static final int LAYER_DURATION_TICKS = 700;
    private static final int CLIENT_TICKS_PER_GAME_TICK = 30;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private KeyManager keyManager;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private StarAfkTimerOverlay overlay;

    @Inject
    private StarAfkTimerConfig config;

    private GameObject starObject;
    private NPC starNpc;
    private WorldPoint starLocation;
    private int starTier = -1;

    private boolean currentlyMiningStar = false;
    private boolean hotkeyDisabled = false;
    private boolean suppressedByNonStarClick = false;
    private int estimatedLayerTicks = -1;

    private final HotkeyListener toggleHotkeyListener = new HotkeyListener(() -> config.toggleHotkey())
    {
        @Override
        public void hotkeyPressed()
        {
            hotkeyDisabled = !hotkeyDisabled;
        }
    };

    private final MouseListener mouseListener = new MouseAdapter()
    {
        @Override
        public MouseEvent mousePressed(MouseEvent mouseEvent)
        {
            if (mouseEvent.getButton() != MouseEvent.BUTTON1)
            {
                return mouseEvent;
            }

            handleLeftClick();

            return mouseEvent;
        }
    };

    @Provides
    StarAfkTimerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(StarAfkTimerConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        keyManager.registerKeyListener(toggleHotkeyListener);
        mouseManager.registerMouseListener(mouseListener);

        hotkeyDisabled = false;
        suppressedByNonStarClick = false;
        resetStar();
    }

    @Override
    protected void shutDown()
    {
        mouseManager.unregisterMouseListener(mouseListener);
        keyManager.unregisterKeyListener(toggleHotkeyListener);
        overlayManager.remove(overlay);

        hotkeyDisabled = false;
        suppressedByNonStarClick = false;
        resetStar();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        switch (event.getGameState())
        {
            case HOPPING:
            case LOGGING_IN:
            case LOGIN_SCREEN:
                resetStar();
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event)
    {
        GameObject object = event.getGameObject();
        int tier = getTier(object.getId());

        if (tier < 0)
        {
            return;
        }

        setStar(object, tier);
    }

    @Subscribe
    public void onGameObjectDespawned(GameObjectDespawned event)
    {
        GameObject object = event.getGameObject();

        if (starObject == null)
        {
            return;
        }

        if (object.equals(starObject) || sameTile(object.getWorldLocation(), starLocation))
        {
            resetStar();
        }
    }

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        NPC npc = event.getNpc();

        if (npc.getId() != STAR_HEALTH_NPC)
        {
            return;
        }

        if (isNpcForCurrentStar(npc))
        {
            starNpc = npc;
            updateLayerTimerFromHealth();
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        if (event.getNpc().equals(starNpc))
        {
            starNpc = null;
            estimatedLayerTicks = -1;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        Player player = client.getLocalPlayer();

        if (player == null)
        {
            currentlyMiningStar = false;
            suppressedByNonStarClick = false;
            return;
        }

        if (starObject == null || starLocation == null)
        {
            scanSceneForStar();
        }

        if (starNpc == null)
        {
            scanForStarNpc();
        }

        if (starLocation == null && starObject == null)
        {
            currentlyMiningStar = false;
            suppressedByNonStarClick = false;
            return;
        }

        boolean miningNow = isLikelyMining(player) && isNearStar(player.getWorldLocation());

        if (!miningNow)
        {
            suppressedByNonStarClick = false;
        }

        currentlyMiningStar = miningNow;

        updateLayerTimerFromHealth();
    }

    boolean shouldRenderOverlay()
    {
        if (!config.enabled())
        {
            return false;
        }

        if (hotkeyDisabled)
        {
            return false;
        }

        if (suppressedByNonStarClick)
        {
            return false;
        }

        if (starLocation == null && starObject == null)
        {
            return false;
        }

        if (!currentlyMiningStar)
        {
            return false;
        }

        return !isOverlaySuppressedByMouse();
    }

    int getStarTier()
    {
        return starTier;
    }

    int getEstimatedLayerTicks()
    {
        return estimatedLayerTicks;
    }

    private void handleLeftClick()
    {
        if (!config.hideOnNonStarClick())
        {
            return;
        }

        if (!config.enabled() || hotkeyDisabled)
        {
            return;
        }

        if (starLocation == null && starObject == null)
        {
            suppressedByNonStarClick = false;
            return;
        }

        MenuEntry[] entries = client.getMenuEntries();

        if (menuContainsStar(entries))
        {
            suppressedByNonStarClick = false;
            return;
        }

        if (currentlyMiningStar)
        {
            suppressedByNonStarClick = true;
        }
    }

    private boolean menuContainsStar(MenuEntry[] entries)
    {
        if (entries == null)
        {
            return false;
        }

        for (MenuEntry entry : entries)
        {
            if (isStarMenuEntry(entry))
            {
                return true;
            }
        }

        return false;
    }

    private boolean isStarMenuEntry(MenuEntry entry)
    {
        if (entry == null)
        {
            return false;
        }

        if (isStarGameObjectAction(entry.getType(), entry.getIdentifier()))
        {
            return true;
        }

        return targetLooksLikeShootingStar(entry.getTarget());
    }

    @SuppressWarnings("deprecation")
    private boolean isStarGameObjectAction(MenuAction action, int identifier)
    {
        if (action == null)
        {
            return false;
        }

        switch (action)
        {
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
            case WIDGET_TARGET_ON_GAME_OBJECT:
            case ITEM_USE_ON_GAME_OBJECT:
                return getTier(identifier) > 0;
            default:
                return false;
        }
    }

    private boolean targetLooksLikeShootingStar(String target)
    {
        if (target == null)
        {
            return false;
        }

        return target.toLowerCase().contains("shooting star");
    }

    private boolean isOverlaySuppressedByMouse()
    {
        if (config.disableOnHover() && isMouseOverCanvas())
        {
            return true;
        }

        if (config.hideOnMouseMovement())
        {
            int requiredClientIdleTicks = config.mouseIdleGameTicks() * CLIENT_TICKS_PER_GAME_TICK;
            return client.getMouseIdleTicks() < requiredClientIdleTicks;
        }

        return false;
    }

    private boolean isMouseOverCanvas()
    {
        Point mousePosition = client.getMouseCanvasPosition();

        if (mousePosition == null)
        {
            return false;
        }

        int x = mousePosition.getX();
        int y = mousePosition.getY();

        return x >= 0
                && y >= 0
                && x < client.getCanvasWidth()
                && y < client.getCanvasHeight();
    }

    private void setStar(GameObject object, int tier)
    {
        WorldPoint location = object.getWorldLocation();

        boolean changed = starLocation == null
                || !sameTile(starLocation, location)
                || starTier != tier;

        starObject = object;
        starLocation = location;
        starTier = tier;

        if (changed)
        {
            estimatedLayerTicks = -1;
            suppressedByNonStarClick = false;
        }

        if (starNpc != null && !isNpcForCurrentStar(starNpc))
        {
            starNpc = null;
        }
    }

    private void scanSceneForStar()
    {
        Scene scene = client.getScene();

        if (scene == null)
        {
            return;
        }

        Tile[][][] tiles = scene.getTiles();
        int plane = client.getPlane();

        if (plane < 0 || plane >= tiles.length)
        {
            return;
        }

        Player player = client.getLocalPlayer();
        WorldPoint playerLocation = player == null ? null : player.getWorldLocation();

        GameObject bestObject = null;
        int bestTier = -1;
        int bestDistance = Integer.MAX_VALUE;

        for (Tile[] row : tiles[plane])
        {
            for (Tile tile : row)
            {
                if (tile == null)
                {
                    continue;
                }

                GameObject[] gameObjects = tile.getGameObjects();

                if (gameObjects == null)
                {
                    continue;
                }

                for (GameObject object : gameObjects)
                {
                    if (object == null)
                    {
                        continue;
                    }

                    int tier = getTier(object.getId());

                    if (tier < 0)
                    {
                        continue;
                    }

                    int distance = playerLocation == null
                            ? 0
                            : playerLocation.distanceTo(object.getWorldLocation());

                    if (distance < bestDistance)
                    {
                        bestObject = object;
                        bestTier = tier;
                        bestDistance = distance;
                    }
                }
            }
        }

        if (bestObject != null)
        {
            setStar(bestObject, bestTier);
        }
    }

    private void scanForStarNpc()
    {
        for (NPC npc : client.getNpcs())
        {
            if (npc.getId() == STAR_HEALTH_NPC && isNpcForCurrentStar(npc))
            {
                starNpc = npc;
                updateLayerTimerFromHealth();
                return;
            }
        }
    }

    private boolean isNpcForCurrentStar(NPC npc)
    {
        if (npc == null)
        {
            return false;
        }

        if (starLocation == null)
        {
            return true;
        }

        return npc.getWorldLocation().distanceTo(starLocation) <= 3;
    }

    private void updateLayerTimerFromHealth()
    {
        if (starNpc == null)
        {
            return;
        }

        int ratio = starNpc.getHealthRatio();
        int scale = starNpc.getHealthScale();

        if (ratio < 0 || scale <= 0)
        {
            return;
        }

        estimatedLayerTicks = Math.max(0, Math.min(
                LAYER_DURATION_TICKS,
                (int) Math.ceil(LAYER_DURATION_TICKS * ((double) ratio / scale))
        ));
    }

    private boolean isLikelyMining(Player player)
    {
        return player.getAnimation() != -1;
    }

    private boolean isNearStar(WorldPoint playerLocation)
    {
        if (playerLocation == null || starLocation == null)
        {
            return false;
        }

        return playerLocation.distanceTo(starLocation) <= 2;
    }

    private boolean sameTile(WorldPoint a, WorldPoint b)
    {
        if (a == null || b == null)
        {
            return false;
        }

        return a.getX() == b.getX()
                && a.getY() == b.getY()
                && a.getPlane() == b.getPlane();
    }

    private int getTier(int objectId)
    {
        switch (objectId)
        {
            case STAR_T1_OBJECT:
                return 1;
            case STAR_T2_OBJECT:
                return 2;
            case STAR_T3_OBJECT:
                return 3;
            case STAR_T4_OBJECT:
                return 4;
            case STAR_T5_OBJECT:
                return 5;
            case STAR_T6_OBJECT:
                return 6;
            case STAR_T7_OBJECT:
                return 7;
            case STAR_T8_OBJECT:
                return 8;
            case STAR_T9_OBJECT:
                return 9;
            default:
                return -1;
        }
    }

    private void resetStar()
    {
        starObject = null;
        starNpc = null;
        starLocation = null;
        starTier = -1;
        currentlyMiningStar = false;
        suppressedByNonStarClick = false;
        estimatedLayerTicks = -1;
    }
}
